package main

import (
	"bufio"
	"os"
	"fmt"
)

func main() {
	s := bufio.NewScanner(os.Stdin)
	s.Split(bufio.ScanWords)
	s.Scan()
	a := s.Text()
	var c int
	for i:=0; i<len(a) ; i++ {
		b := a[i] - '0'
		if 9 -b < b {
			if i==0 && b==9 {
				c=9
			} else {
				c = int(9 - b)
			}
		} else {
			c=int(b)
		}
		fmt.Print(c)
	}
}
